(* [comment removed for export] *)
Definition kc_res (a b : list byte) : Z := if key_lt (zbytes a) (zbytes b) then 1 else 0.

(* [comment removed for export] *)
Definition kcmp1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (k nm : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (kc_res k nm)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [] m m' /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ m' = m.

Definition kcmp1_stmt : Prop := forall (kp v : Z) (k nm : list byte) (rest : list cell)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at rsegs m kp k -> zlength k < 2^64 ->
  rw_cells rsegs m v (C2 (wz (zlength nm + 2)) :: rest) ->
  bytes_at rsegs m (v + 8) nm ->
  zlength nm + 2 < 2^16 ->
  mem_inv rsegs m ->
  evt rsegs (kcmp1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc k nm m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (wz kp) (wz (zlength k)) (wz v) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_KEY_COMPARE_SV_VT) fc None m (seg_rom rsegs)).
Scheme kc__1 := Elimination for Corelib.Init.Datatypes.option Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Logic.and Sort Prop.

(* [comment removed for export] *)
Lemma kcmp1_loop : forall (cnt i : nat) (kp v : Z) (k nm : list byte) (rest : list cell)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (cnt = length nm - i)%nat -> (i < length nm)%nat -> length k = length nm ->
  ilex (zbytes k) (zbytes nm) = ilex (zbytes (skipn i k)) (zbytes (skipn i nm)) ->
  bytes_at rsegs m kp k -> zlength k < 2^64 ->
  rw_cells rsegs m v (C2 (wz (zlength nm + 2)) :: rest) ->
  bytes_at rsegs m (v + 8) nm ->
  zlength nm + 2 < 2^16 ->
  mem_inv rsegs m ->
  evt rsegs (kcmp1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc k nm m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (wz (kp + Z.of_nat i)) (wz (zlength nm - Z.of_nat i)) (wz (v + 8 + Z.of_nat i))
              (wz (zlength nm - 1 - Z.of_nat i)) a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x33a6c) fc None m (seg_rom rsegs)).
Proof.
