(* [comment removed for export] *)
(* [comment removed for export] *)
Definition kcmp2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (nm k : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (kc_res nm k)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [] m m' /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ m' = m.

Definition kcmp2_stmt : Prop := forall (v kp : Z) (nm k : list byte) (rest : list cell)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m v (C2 (wz (zlength nm + 2)) :: rest) ->
  bytes_at rsegs m (v + 8) nm ->
  zlength nm + 2 < 2^16 ->
  bytes_at rsegs m kp k -> zlength k < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (kcmp2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc nm k m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (wz v) (wz kp) (wz (zlength k)) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_KEY_COMPARE_VT_SV) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
Lemma kcmp2_loop : forall (cnt i : nat) (v kp : Z) (nm k : list byte) (rest : list cell)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (cnt = length nm - i)%nat -> (i < length nm)%nat -> length k = length nm ->
  ilex (zbytes nm) (zbytes k) = ilex (zbytes (skipn i nm)) (zbytes (skipn i k)) ->
  rw_cells rsegs m v (C2 (wz (zlength nm + 2)) :: rest) ->
  bytes_at rsegs m (v + 8) nm ->
  zlength nm + 2 < 2^16 ->
  bytes_at rsegs m kp k -> zlength k < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (kcmp2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc nm k m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (wz (v + 8 + Z.of_nat i)) (wz (kp + Z.of_nat i)) (wz (zlength nm - 1 - Z.of_nat i))
              (wz (zlength nm - Z.of_nat i)) a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x33ca0) fc None m (seg_rom rsegs)).
