(* [comment removed for export] *)
Definition PREV_NODE_STACK : Z := 16.

Definition prevn_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (ns : NS) (r lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ NSCells m' ns.

Definition prevn_stmt : Prop := forall (p : Z) (ns : NS) (fuel : nat) (r lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  NSCells m ns -> ns_out ns lo (bv_unsigned sp) ->
  prev_node fuel ns p = Some r ->
  stk rsegs m lo (bv_unsigned sp) -> lo + PREV_NODE_STACK <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (prevn_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns r lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz p) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_RB_PREV_NODE) fc None m (seg_rom rsegs)).

Section PrevNode.
  Variables (ra sp gp tp s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : mem) (ns : NS) (lo : Z) (s0 : word).
  Hypothesis OUT : ns_out ns lo (bv_unsigned sp).
  Hypothesis LO : lo + 16 <= bv_unsigned sp.
  Hypothesis HC : hceil <= lo.

  (* [comment removed for export] *)
  Definition prevn_ctx (m1 : mem) : Prop :=
    rw_cells rsegs m1 (bv_unsigned sp + -16) [C8 s0; C8 ra]
    /\ stk rsegs m1 lo (bv_unsigned sp + -16)
    /\ NSCells m1 ns
    /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

  (* [comment removed for export] *)
  Lemma prevn_exit : forall m1 (x1 x5 x6 x7 a0 a1 a2 a3 a4 a5 a6 a7 x28 x29 x30 x31 : word) (r : Z),
    prevn_ctx m1 ->
    evt rsegs (prevn_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns r lo m)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp x5 x6 x7 (wz r) s1 a0 a1 a2 a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
