  (* [comment removed for export] *)
  Lemma prevn_max_loop : forall fuel (n r : Z) m1 (x1 x5 x6 x7 s0x a1 a2 a3 a4 a5 a6 a7 x28 x29 x30 x31 : word),
    prevn_ctx m1 -> maximum fuel ns n = Some r ->
    evt rsegs (prevn_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns r lo m)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp x5 x6 x7 s0x s1 (wz n) a1 a2 a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
