  (* [comment removed for export] *)
  Lemma prevn_climb_loop : forall fuel (cur r : Z) m1 (x1 x5 x6 x7 a0 a1 a2 a3 a4 a5 a6 a7 x28 x29 x30 x31 : word),
    prevn_ctx m1 -> oloop fuel (prev_climb_step ns) cur = Some r ->
    evt rsegs (prevn_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ns r lo m)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp x5 x6 x7 (wz cur) s1 a0 a1 a2 a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
          F (Z_to_bv 64 0x33f80) fc None m1 (seg_rom rsegs)).
  Proof.
    induction fuel as [|fuel IH]; intros until x31; intros CTX CL; [cbn in CL; discriminate|].
    pose proof CTX as (FR & ST & NC & MU & WM & MI).
    pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. change (2 ^ Z.of_N 64) with (2^64) in SPR.
    rewrite oloop_S in CL.
    destruct (ns !! cur) as [ndc|] eqn:Lc. 2:{ exfalso. unfold prev_climb_step, get_parent, load in CL. rewrite Lc in CL. discriminate. }
    destruct (ns !! (n_par ndc)) as [ndx|] eqn:Lx.
    2:{ exfalso. unfold prev_climb_step, get_parent, get_left, load in CL. rewrite Lc in CL. cbn [mbind option_bind get_field OFF_PARENT Z.eqb] in CL.
        rewrite Lx in CL. discriminate. }
    rewrite (prev_climb_step_eq _ _ _ _ Lc Lx) in CL. cbn [mbind option_bind] in CL.
    pose proof (NSCells_wf _ _ _ _ NC Lc) as WFc. unfold node_wf in WFc.
    pose proof (NSCells_wf _ _ _ _ NC Lx) as WFx. unfold node_wf in WFx.
    destruct (NSCells_lookup _ _ _ _ NC Lc) as [padc CHc]. unfold NodeCells, wz in CHc.
    pose proof (rw_cells_bound _ _ _ _ CHc) as CHcB. cbn [cells_size csize Nat.add] in CHcB.
    destruct (NSCells_lookup _ _ _ _ NC Lx) as [padx CHx]. unfold NodeCells, wz in CHx. unfold wz.
    (* [comment removed for export] *)
    step. step. step. step. if_cases K; zify_cond K.
    - replace (cur =? n_lft ndx) with true in CL by (symmetry; apply Z.eqb_eq; lia).
      eapply IH; [exact CTX| exact CL].
    - replace (cur =? n_lft ndx) with false in CL by (symmetry; apply Z.eqb_neq; lia). injection CL as <-.
      eapply prevn_exit. exact CTX.
  Qed.
End PrevNode.

