(* [comment removed for export] *)

(* [comment removed for export] *)
Definition UBL_STACK : Z := 48.

Definition ubl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (h : Z) (S : list Z) (ns : NS) (em : gmap Z elt) (r lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ TreeR m' h S ns em.

Definition ubl_stmt : Prop := forall (x y kv kp : Z) (k : list byte) (h : Z) (S : list Z) (ns : NS) (em : gmap Z elt)
    (fuel : nat) (r lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  TreeR m h S ns em -> (x = 0 \/ x ∈ S) -> 0 <= y < 2^64 ->
  rw_cells rsegs m kv [C8 (wz kp); C8 (wz (zlength k))] -> bytes_at rsegs m kp k ->
  upper_bound_loop fuel (cmpU key_lt (key_of em) (zbytes k)) ns x y = Some r ->
  stk rsegs m lo (bv_unsigned sp) -> lo + UBL_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= h ->
  (kv + 16 <= lo \/ bv_unsigned sp <= kv) ->
  (kp + zlength k <= lo \/ bv_unsigned sp <= kp) ->
  mem_inv rsegs m ->
  evt rsegs (ubl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc h S ns em r lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz x) (wz y) (wz kv) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_RB_UPPER_BOUND_LOOP) fc None m (seg_rom rsegs)).

Section UBL.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : mem) (kv kp : Z) (k : list byte) (h : Z) (S : list Z) (ns : NS) (em : gmap Z elt) (lo : Z).
  Hypothesis LO : lo + 48 <= bv_unsigned sp.
  Hypothesis HC : hceil <= lo.
  Hypothesis HH : bv_unsigned sp <= h.
  Hypothesis SEP1 : kv + 16 <= lo \/ bv_unsigned sp <= kv.
  Hypothesis SEP2 : kp + zlength k <= lo \/ bv_unsigned sp <= kp.

  Definition ubl_ctx (m1 : mem) (j16 : list byte) : Prop :=
    rw_cells rsegs m1 (bv_unsigned sp + -48) [CB 16 j16; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ stk rsegs m1 lo (bv_unsigned sp + -48)
    /\ TreeR m1 h S ns em
    /\ rw_cells rsegs m1 kv [C8 (wz kp); C8 (wz (zlength k))] /\ bytes_at rsegs m1 kp k
    /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

  #[local] Abbreviation POST r := (ubl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc h S ns em r lo m).

  (* [comment removed for export] *)
  Lemma ubl_exit : forall m1 j16 (x1 x5 x6 x7 s0x s1x a1 a2 a3 a4 a5 a6 a7 s2x x28 x29 x30 x31 : word) (r : Z),
    ubl_ctx m1 j16 ->
    evt rsegs (POST r)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp x5 x6 x7 s0x s1x (wz r) a1 a2 a3 a4 a5 a6 a7
               s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
