Scheme kc__6 := Elimination for Corelib.Init.Logic.or Sort Prop.

  (* [comment removed for export] *)
  Lemma ubl_loop : forall fuel (x y r : Z) m1 j16 (x1 x5 x6 x7 a0 a1 a2 a3 a4 a5 a6 a7 x28 x29 x30 x31 : word),
    ubl_ctx m1 j16 -> x ∈ S -> 0 <= y < 2^64 ->
    oloop fuel (upper_bound_step (cmpU key_lt (key_of em) (zbytes k)) ns) (x, y) = Some r ->
    evt rsegs (POST r)
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp x5 x6 x7 (wz kv) (wz x) a0 a1 a2 a3 a4 a5 a6 a7
               (wz y) s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
