(* [comment removed for export] *)
Definition FFIND_STACK : Z := 144.

Definition ffind_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa : Z) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (res r lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (res, res + 8)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' res [C8 (wz r)]
    /\ FieldsC m' Fa S L ns ls em.

Definition ffind_stmt : Prop := forall (res Fa kp : Z) (k : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt)
    (fuel : nat) (r lo : Z) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  FieldsC m Fa S L ns ls em ->
  bytes_at rsegs m kp k -> rw_cells rsegs m res [CB 8 rj] ->
  fields_find fuel (cmpL key_lt (key_of em) (zbytes k)) (cmpU key_lt (key_of em) (zbytes k)) ns ls Fa = Some r ->
  stk rsegs m lo (bv_unsigned sp) -> lo + FFIND_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= Fa ->
  (kp + zlength k <= lo \/ bv_unsigned sp <= kp) -> bv_unsigned sp <= res -> res + 8 <= Fa ->
  mem_inv rsegs m ->
  evt rsegs (ffind_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa S L ns ls em res r lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz Fa) (wz kp) (wz (zlength k)) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FIELDS_FIND_SV) fc None m (seg_rom rsegs)).

